class Solution {
public:
    int sum = 0;
    void walk(TreeNode* node, bool isLeft) {
        if (!node) return;
        if (!node->left && !node->right && isLeft) sum += node->val;
        walk(node->left, true);
        walk(node->right, false);
    }
    int sumOfLeftLeaves(TreeNode* root) {
        walk(root, false);
        return sum;
    }
};
